#!/usr/bin/env python3

# Target P53 amino acid sequence
target_sequence = ""

# Plasmid sequences
plasmids = {
    "A": "",
    "B": "",
    "C": "",
    "D": ""
}

# Standard genetic code
genetic_code = {
    'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
    'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
    'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
    'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
    'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
    'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
    'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
    'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
    'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
    'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
    'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
    'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
    'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
    'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
    'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
    'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G'
}

def translate_dna(dna_sequence):
    """Translate DNA sequence to amino acid sequence"""
    protein = ""
    for i in range(0, len(dna_sequence), 3):
        codon = dna_sequence[i:i+3]
        if len(codon) == 3:
            amino_acid = genetic_code.get(codon, 'X')
            if amino_acid == '*':  # Stop codon
                break
            protein += amino_acid
        else:
            break  # Incomplete codon
    return protein

def find_differences(target, translated):
    """Find differences between target and translated sequences"""
    differences = []
    min_len = min(len(target), len(translated))
    
    for i in range(min_len):
        if target[i] != translated[i]:
            differences.append((i+1, target[i], translated[i]))
    
    # Check length differences
    if len(target) != len(translated):
        differences.append(("Length", len(target), len(translated)))
    
    return differences

# Main analysis
print("Human P53 Plasmid Selection Analysis")
print("=" * 50)
print(f"Target P53 sequence: {len(target_sequence)} amino acids")
print()

perfect_matches = []
results = {}

for plasmid_id in ["A", "B", "C", "D"]:
    dna_seq = plasmids[plasmid_id]
    translated = translate_dna(dna_seq)
    results[plasmid_id] = translated
    
    print(f"Plasmid {plasmid_id}:")
    print(f"  DNA length: {len(dna_seq)} bp")
    print(f"  Translated length: {len(translated)} AA")
    
    # Compare with target
    differences = find_differences(target_sequence, translated)
    
    if not differences:
        print("  ✓ PERFECT MATCH")
        perfect_matches.append(plasmid_id)
    else:
        identity = ((min(len(target_sequence), len(translated)) - len([d for d in differences if d[0] != "Length"])) / len(target_sequence)) * 100
        print(f"  Identity: {identity:.1f}%")
        
        for diff in differences:
            if diff[0] == "Length":
                print(f"    Length mismatch: target={diff[1]}, plasmid={diff[2]}")
            else:
                pos, target_aa, actual_aa = diff
                codon_start = (pos - 1) * 3
                codon = dna_seq[codon_start:codon_start + 3] if codon_start < len(dna_seq) else "???"
                print(f"    Position {pos}: {target_aa} → {actual_aa} (codon: {codon})")
    print()

print("RECOMMENDATION:")
if perfect_matches:
    print(f"Use plasmid(s): {', '.join(perfect_matches)}")
    print("These plasmids will produce the exact target P53 protein sequence.")
else:
    print("No perfect matches found. All plasmids contain sequence errors.")